A priority queue is useful here because edge weights are positive, but the answer is a path rather than just a distance. The `parent` array handles that second part. Every time a shorter route to a node is found, its parent is updated too.

The graph is built in both directions. If node `n` never gets a finite distance, the required result is `[-1]`.

```java
import java.util.*;

class Solution {
    public List<Integer> shortestPath(int n, int m, int[][] edges) {
        List<List<int[]>> graph = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            graph.add(new ArrayList<>());
        }

        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            int weight = edge[2];
            graph.get(u).add(new int[]{v, weight});
            graph.get(v).add(new int[]{u, weight});
        }

        long[] distance = new long[n + 1];
        Arrays.fill(distance, Long.MAX_VALUE);
        int[] parent = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            parent[i] = i;
        }

        PriorityQueue<long[]> queue = new PriorityQueue<>(
            Comparator.comparingLong(value -> value[0])
        );

        distance[1] = 0;
        queue.offer(new long[]{0, 1});

        while (!queue.isEmpty()) {
            long[] current = queue.poll();
            long currentDistance = current[0];
            int node = (int) current[1];

            if (currentDistance != distance[node]) {
                continue;
            }

            for (int[] edge : graph.get(node)) {
                int next = edge[0];
                int weight = edge[1];
                long newDistance = currentDistance + weight;

                if (newDistance < distance[next]) {
                    distance[next] = newDistance;
                    parent[next] = node;
                    queue.offer(new long[]{newDistance, next});
                }
            }
        }

        if (distance[n] == Long.MAX_VALUE) {
            return new ArrayList<>(Collections.singletonList(-1));
        }

        LinkedList<Integer> path = new LinkedList<>();
        int node = n;
        while (parent[node] != node) {
            path.addFirst(node);
            node = parent[node];
        }
        path.addFirst(1);
        return new ArrayList<>(path);
    }
}
```

The one-node case also works: node `1` is already the destination, so the returned path is `[1]`. The input edge list is not changed.

Time: `O((n + m) log n)`.
Space: `O(n + m)`.

The graph is undirected, so every edge is added in both directions. Dijkstra's algorithm keeps the smallest known distance for each node, while `parent` remembers where that node was reached from.

After reaching node `n`, the parent links are followed backward and then reversed. For example, if the best route is `1 -> 3 -> 5`, the stored parents rebuild that same route.

```cpp
#include <bits/stdc++.h>
using namespace std;

class Solution{
public:
    vector<int> shortestPath(int n, int m, vector<vector<int>> &edges) {
        vector<vector<pair<int, int>>> graph(n + 1);
        for (const auto &edge : edges) {
            int u = edge[0];
            int v = edge[1];
            int weight = edge[2];
            graph[u].push_back({v, weight});
            graph[v].push_back({u, weight});
        }

        const long long INF = LLONG_MAX / 4;
        vector<long long> distance(n + 1, INF);
        vector<int> parent(n + 1);
        for (int node = 1; node <= n; node++) {
            parent[node] = node;
        }

        priority_queue<pair<long long, int>,
                       vector<pair<long long, int>>,
                       greater<pair<long long, int>>> pq;

        distance[1] = 0;
        pq.push({0, 1});

        while (!pq.empty()) {
            auto [currentDistance, node] = pq.top();
            pq.pop();

            if (currentDistance != distance[node]) {
                continue;
            }

            for (auto [nextNode, weight] : graph[node]) {
                long long newDistance = currentDistance + weight;
                if (newDistance < distance[nextNode]) {
                    distance[nextNode] = newDistance;
                    parent[nextNode] = node;
                    pq.push({newDistance, nextNode});
                }
            }
        }

        if (distance[n] == INF) {
            return {-1};
        }

        vector<int> path;
        int node = n;
        while (parent[node] != node) {
            path.push_back(node);
            node = parent[node];
        }
        path.push_back(1);
        reverse(path.begin(), path.end());
        return path;
    }
};
```

Dry run: if the parent array gives `parent[5] = 3` and `parent[3] = 1`, starting at `5` collects `5, 3, 1`. Reversing it returns `1, 3, 5`.

Time complexity: `O((n + m) log n)`.
Space complexity: `O(n + m)`.

Instead of storing a parent array, this version carries the current path inside each heap entry. When a node is removed from the heap for the first time, its path is the shortest one to that node. This makes the returned result easy to see in the code.

A `visited` set prevents later, longer entries for the same node from being expanded. The graph is undirected, so both adjacency entries are added.

```python
import heapq

class Solution:
    def shortestPath(self, n, m, edges):
        graph = [[] for _ in range(n + 1)]
        for u, v, weight in edges:
            graph[u].append((v, weight))
            graph[v].append((u, weight))

        heap = [(0, 1, (1,))]
        visited = set()

        while heap:
            distance, node, path = heapq.heappop(heap)

            if node in visited:
                continue
            visited.add(node)

            if node == n:
                return list(path)

            for next_node, weight in graph[node]:
                if next_node not in visited:
                    heapq.heappush(
                        heap,
                        (distance + weight, next_node, path + (next_node,))
                    )

        return [-1]
```

Dry run: the heap starts with `(0, 1, (1,))`. If node `2` is reached next, its entry contains `(cost, 2, (1, 2))`. When node `n` is popped, the tuple already contains the full route.

This is convenient for a small graph, but copying tuples can take extra time compared with storing just parent pointers. The input is not modified.

Time complexity: `O((n + m) log n)` heap work, with extra path-copying cost in the worst case.
Space complexity: `O(n + m)` for the graph and queued states, apart from stored path copies.

For a small graph, an all-pairs table is another simple option. `distance[i][j]` stores the cheapest cost from `i` to `j`. During the Floyd-Warshall updates, `nextNode[i][j]` stores the first node to take after `i`, which makes path rebuilding straightforward.

Parallel edges are handled by keeping only the lighter one. If the destination stays unreachable, the method returns `{-1}`.

```cpp
#include <bits/stdc++.h>
using namespace std;

class Solution{
public:
    vector<int> shortestPath(int n, int m, vector<vector<int>> &edges) {
        const long long INF = LLONG_MAX / 4;
        vector<vector<long long>> distance(n + 1, vector<long long>(n + 1, INF));
        vector<vector<int>> nextNode(n + 1, vector<int>(n + 1, -1));

        for (int i = 1; i <= n; i++) {
            distance[i][i] = 0;
            nextNode[i][i] = i;
        }

        for (const auto &edge : edges) {
            int u = edge[0];
            int v = edge[1];
            int weight = edge[2];

            if (weight < distance[u][v]) {
                distance[u][v] = weight;
                distance[v][u] = weight;
                nextNode[u][v] = v;
                nextNode[v][u] = u;
            }
        }

        for (int middle = 1; middle <= n; middle++) {
            for (int from = 1; from <= n; from++) {
                if (distance[from][middle] == INF) {
                    continue;
                }

                for (int to = 1; to <= n; to++) {
                    long long throughMiddle = distance[from][middle] + distance[middle][to];
                    if (throughMiddle < distance[from][to]) {
                        distance[from][to] = throughMiddle;
                        nextNode[from][to] = nextNode[from][middle];
                    }
                }
            }
        }

        if (nextNode[1][n] == -1) {
            return {-1};
        }

        vector<int> path;
        int node = 1;
        path.push_back(node);

        while (node != n) {
            node = nextNode[node][n];
            if (node == -1) {
                return {-1};
            }
            path.push_back(node);
        }

        return path;
    }
};
```

The graph and input edge list are kept unchanged. This is not a good choice for a very large `n`, because the distance table needs quadratic memory.

Time complexity: `O(n^3)`.
Space complexity: `O(n^2)`.
